        vm.deal(address(c), VALUE_CAP);
        vm.assume(amount > 0);
        vm.assume(address(this).balance >= amount);
        uint beforeBal = address(c).balance;
        uint beforeTestBal = address(this).balance;
        try c.deposit{value: amount}() {} catch { return; }
        vm.assume(c.deposit.selector == bytes4(0));
        try c.withdrawAll() {} catch { return; }
        uint afterBal = address(c).balance;
        uint afterTestBal = address(this).balance;
        assertTrue(afterBal == beforeBal && afterTestBal == beforeTestBal);
    }

    function testFuzz_run(uint256 amount) public {
        _run(amount);
    }

