contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(uint256 amount) public payable {
        require(address(this).balance >= amount);

        // Set up: give msg.sender (this test contract) a credited balance.
        c.deposit{value: amount}();

        // Make the deciding call as its own top-level statement.
        uint256 balanceBefore = address(this).balance;
        bool reverted;
        try c.withdrawAll() {
            reverted = false;
        } catch {
            reverted = true;
        }

        // With no remaining credit, withdrawAll must not revert and must not send Ether.
        assert(!reverted && address(this).balance == balanceBefore);
    }

    receive() external payable {}
}

contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(uint256 amount) public payable {
        require(amount > 0);
        require(address(this).balance >= amount);

        c.deposit{value: amount}();

        uint256 balBefore = address(this).balance;
        uint256 credBefore = c.credit(address(this));
        require(credBefore >= amount);

        bool reverted;
        try c.withdrawAll() {
            reverted = false;
        } catch {
            reverted = true;
        }

        assert(!reverted && address(this).balance == balBefore + amount && c.credit(address(this)) == credBefore - amount);
    }

    receive() external payable {}
}

